#!/bin/bash
# land-glass-cards.sh — The cards turn to glass.
#
# The medical cards frost to .78 white glass: the amber and the wisps glow
# through, the ink stays dark, and the alpha is the exact limit the contrast
# arithmetic allows — computed at BOTH ends of the sky, because a dark ink's
# worst ground is the darkest tan and a light ink's is the lightest. The card
# ink table darkens with it, and the test now asserts AA on the frosted pane
# rather than equality with the root.
#
# WEB ONLY. Push and Vercel takes it.
#
# Run from the repo root:  bash land-glass-cards.sh
set -euo pipefail

cd "$(dirname "$0")"
[ -d together-city-react ] || { echo "!! Run this from the Together-Ai repo root."; exit 1; }

LOG="$(git log --oneline -40)"
MARK="The Medical Hub breathes amber"
case "$LOG" in
  *"$MARK"*) ;;
  *) echo "!! This patch applies on top of \"$MARK\" — run land-medical-atmosphere.sh first."; exit 1 ;;
esac
NEEDS="The cards turn to glass"
case "$LOG" in
  *"$NEEDS"*) echo "== \"$NEEDS\" is already here. Nothing to do."; exit 0 ;;
esac
DIRTY="$(git status --porcelain | grep -Ev '^\?\? (land-.*\.sh|push-.*\.sh|.*\.patch)$' || true)"
if [ -n "$DIRTY" ]; then
  echo "!! Working tree is dirty. Commit or stash first:"; echo "$DIRTY"; exit 1
fi

PATCH="$(mktemp "${TMPDIR:-/tmp}/glasscards.XXXXXX")"
trap 'rm -f "$PATCH"' EXIT
cat <<'B64EOF' | tr -d '\n' | openssl base64 -d -A > "$PATCH"

B64EOF

WANT="157f54f8e4a5dcac08bdecfd57c5aa62b1e7e308563e98345624e668de013021"
GOT="$(shasum -a 256 "$PATCH" | awk '{print $1}')"
[ "$GOT" = "$WANT" ] || { echo "!! Patch is corrupt."; echo "   want $WANT"; echo "   got  $GOT"; exit 1; }
echo "== patch verified"
git apply --check -C1 "$PATCH" || { echo "!! Patch does not apply cleanly. Nothing written."; exit 1; }
git am --keep-cr -C1 < "$PATCH"
echo "== committed"

cd together-city-react
npx tsc --noEmit
npx vitest run
npx eslint src || true
node scripts/lint-ceiling.mjs
node scripts/dead-export-audit.mjs
node scripts/motion-ceiling.mjs
node scripts/a11y-audit.mjs
node scripts/nav-audit.mjs
npx vite build
cd ..

echo
echo "==============================================================="
echo " Landed: $NEEDS — push and Vercel ships it."
echo "==============================================================="
